module TopModule (
    input  clock,
    input  a,
    output p,
    output reg q
);
    reg seen_a;

    initial begin
        q = 1'b0;
        seen_a = 1'b0;
    end

    always @(posedge clock) begin
        if (a) begin
            seen_a = 1'b1;
        end
    end

    always @(negedge clock) begin
        if (seen_a) begin
            q = ~q;
        end
        seen_a = 1'b0;
    end

    assign p = clock ? a : q;

endmodule

