    input  a,
    output reg p,
    output reg q
);
    reg seen_a;

    initial begin
        q = 1'b0;
        seen_a = 1'b0;
        p = 1'b0;
    end

    always @(posedge clock or negedge clock) begin
        if (!clock) begin
            seen_a = 1'b0;
            q = q ^ seen_a; // toggle q on falling edge if seen_a
            p = q;
        end else begin
            if (a) seen_a = 1'b1;
            p = a;
        end
    end

endmodule

